style.css:
@-moz-document domain("roblox.com") {
/* Header & nav */
  .rbx-header {
    background-color: #0074BD !important;
    height: 41px !important;
  }
  .rbx-navbar li .nav-menu-title:hover {
    background-color: rgba(25,25,25,0.1) !important;
  }

  /* Fonts */
  body, .rbx-header, .rbx-nav {
    font-family: 'Source Sans Pro', sans-serif !important;
  }
  .rbx-header .logo, .rbx-title {
    font-family: 'Gill Sans Ultra Bold', sans-serif !important;
  }

  /* Game cards */
  .game-card {
    border: 1px solid #ddd;
    border-radius: 2px;
    padding: 8px;
    transition: background 0.2s;
  }
  .game-card:hover {
    background: #f5f5f5;
  }

  /* Sidebar items */
  .sidebar-item:hover {
    background-color: rgba(25,25,25,0.05) !important;
  }
}
